package br.com.confirmacao.auth.application;import br.com.confirmacao.auth.domain.PasswordResetToken;import br.com.confirmacao.auth.infrastructure.PasswordResetTokenRepository;import br.com.confirmacao.user.domain.User;import br.com.confirmacao.user.infrastructure.UserRepository;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.crypto.password.PasswordEncoder;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import java.nio.charset.StandardCharsets;import java.security.*;import java.time.*;import java.util.*;
@Service public class PasswordResetService{private final UserRepository users;private final PasswordResetTokenRepository tokens;private final PasswordEncoder passwords;private final SecureRandom random=new SecureRandom();private final Duration expiration;private final boolean expose;public PasswordResetService(UserRepository u,PasswordResetTokenRepository t,PasswordEncoder p,@Value("${app.password-reset.expiration:PT30M}")Duration e,@Value("${app.password-reset.expose-token:false}")boolean x){users=u;tokens=t;passwords=p;expiration=e;expose=x;}@Transactional public PasswordResetRequestResult request(String email){var found=users.findByEmailIgnoreCase(email.trim());if(found.isEmpty()||!found.get().isActive())return new PasswordResetRequestResult(null,null);var u=found.get();var now=Instant.now();tokens.invalidateUnusedByUserId(u.getId(),now);String raw=generate();tokens.save(new PasswordResetToken(u,hash(raw),now.plus(expiration)));return new PasswordResetRequestResult(expose?raw:null,u);}@Transactional public User reset(String raw,String pass){var now=Instant.now();var token=tokens.findByTokenHash(hash(raw)).filter(t->t.isValidAt(now)).orElseThrow(InvalidPasswordResetTokenException::new);var u=token.getUser();if(!u.isActive())throw new InvalidPasswordResetTokenException();u.changePasswordHash(passwords.encode(pass));token.markAsUsed(now);return u;}private String generate(){byte[]b=new byte[32];random.nextBytes(b);return Base64.getUrlEncoder().withoutPadding().encodeToString(b);}private String hash(String v){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(v.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}}}
